    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen',
        'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue',
        sans-serif;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 20px;
}

.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: #000;
    color: #fff;
    padding: 8px;
    text-decoration: none;
    z-index: 100;
}

.skip-link:focus {
    top: 0;
}

.container {
    width: 100%;
    max-width: 500px;
}

main {
    width: 100%;
}

.page-header {
    text-align: center;
    margin-bottom: 40px;
    animation: slideDown 0.6s ease-out;
}

@keyframes slideDown {
    from {
        opacity: 0;
        transform: translateY(-20px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.page-header h1 {
    font-size: 32px;
    font-weight: 700;
    color: #fff;
    margin-bottom: 8px;
}

.subtitle {
    font-size: 16px;
    color: rgba(255, 255, 255, 0.9);
    font-weight: 400;
}

.form {
    background: #fff;
    border-radius: 12px;
    padding: 40px;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
    animation: slideUp 0.6s ease-out;
}

@keyframes slideUp {
    from {
        opacity: 0;
        transform: translateY(20px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.form-field {
    margin-bottom: 32px;
}

fieldset {
    border: none;
    padding: 0;
}

legend {
    font-size: 18px;
    font-weight: 600;
    color: #1a1a1a;
    margin-bottom: 12px;
    display: block;
    padding: 0;
}

.help-text {
    font-size: 14px;
    color: #666;
    margin-bottom: 20px;
    display: block;
}

.radio-group {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.radio-option {
    display: flex;
    align-items: center;
}

.radio-option input[type="radio"] {
    appearance: none;
    -webkit-appearance: none;
    width: 0;
    height: 0;
    margin: 0;
    padding: 0;
    position: absolute;
    opacity: 0;
}

.radio-option input[type="radio"]:focus + label {
    outline: 2px solid #667eea;
    outline-offset: 2px;
    border-radius: 8px;
}

.radio-option input[type="radio"]:focus:not(:focus-visible) + label {
    outline: none;
}

.radio-option label {
    display: flex;
    align-items: center;
    cursor: pointer;
    font-size: 16px;
    color: #1a1a1a;
    user-select: none;
    padding: 12px;
    border-radius: 8px;
    transition: background-color 0.2s ease;
}

.radio-option label:hover {
    background-color: #f5f5f5;
}

.radio-option input[type="radio"]:checked + label {
    background-color: #f0f0ff;
}

.radio-custom {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 24px;
    height: 24px;
    border: 2px solid #ccc;
    border-radius: 50%;
    margin-right: 12px;
    transition: all 0.2s ease;
    flex-shrink: 0;
}

.radio-option input[type="radio"]:checked + label .radio-custom {
    border-color: #667eea;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    box-shadow: inset 0 0 0 3px #fff;
}

.label-text {
    font-weight: 500;
}

.form-actions {
    margin-top: 32px;
}

.btn {
    padding: 12px 32px;
    font-size: 16px;
    font-weight: 600;
    border: none;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.2s ease;
    width: 100%;
}

.btn-primary {
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    color: #fff;
}

.btn-primary:hover:not(:disabled) {
    transform: translateY(-2px);
    box-shadow: 0 10px 25px rgba(102, 126, 234, 0.4);
}

.btn-primary:active:not(:disabled) {
    transform: translateY(0);
}

.btn:focus {
    outline: 2px solid #667eea;
    outline-offset: 2px;
}

.btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.success-message {
    margin-top: 20px;
    padding: 16px;
    background-color: #e8f5e9;
    color: #2e7d32;
    border-radius: 8px;
    font-size: 16px;
    text-align: center;
    border-left: 4px solid #4caf50;
}

/* Responsive design */
@media (max-width: 480px) {
    .form {
        padding: 24px;
    }

    .page-header h1 {
        font-size: 24px;
    }

    legend {
        font-size: 16px;
    }

    .btn {
        padding: 12px 24px;
        font-size: 16px;
    }
}

/* High contrast mode support */
@media (prefers-contrast: more) {
    .radio-custom {
        border-width: 3px;
    }

    .radio-option input[type="radio"]:checked + label .radio-custom {
        border-width: 3px;
    }

    legend {
        font-weight: 700;
    }

    .label-text {
        font-weight: 700;
    }
}

/* Reduced motion support */
@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
    }
}

/* Forced colors mode (Windows High Contrast) */
@media (forced-colors: active) {
    .form {
        border: 2px solid CanvasText;
    }

    .radio-custom {
        border-color: CanvasText;
    }

    .radio-option input[type="radio"]:checked + label .radio-custom {
        background: CanvasText;
        border-color: CanvasText;
    }

    .btn-primary {
        background: HighlightText;
        color: Highlight;
    }

    .page-header h1 {
        color: CanvasText;
    }
}
